// Re-encode generated transparent atlases and record each frame's foot anchor.
// Usage: node scripts/prepare-frog-frames.mjs motion.png combat.png footwork.png
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { chromium } from '@playwright/test';

const inputs = process.argv.slice(2);
if (inputs.length !== 3) throw new Error('Provide the motion, combat and footwork PNG paths.');
const cached = join(homedir(), '.cache/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-linux64/chrome-headless-shell');
const executablePath = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE || (existsSync(cached) ? cached : undefined);
const browser = await chromium.launch({ executablePath });
const atlases = {};
try {
  const page = await browser.newPage();
  await mkdir('assets/animation', { recursive: true });
  for (const [index, name] of ['motion', 'combat', 'footwork'].entries()) {
    const data = (await readFile(inputs[index])).toString('base64');
    const result = await page.evaluate(async base64 => {
      const image = new Image(); image.src = `data:image/png;base64,${base64}`; await image.decode();
      if (image.width !== 1536 || image.height !== 1024) throw new Error('Expected a 1536×1024 atlas.');
      const canvas = document.createElement('canvas'); canvas.width = image.width; canvas.height = image.height;
      const ctx = canvas.getContext('2d'); ctx.drawImage(image, 0, 0);
      const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
      const frames = [];
      for (let row = 0; row < 4; row++) {
        const cells = [];
        for (let col = 0; col < 6; col++) {
          let left = 256, top = 256, right = 0, bottom = 0, solid = 0;
          for (let y = 0; y < 256; y++) for (let x = 0; x < 256; x++) {
            if (pixels[((row * 256 + y) * canvas.width + col * 256 + x) * 4 + 3] < 48) continue;
            left = Math.min(left, x); right = Math.max(right, x + 1);
            top = Math.min(top, y); bottom = Math.max(bottom, y + 1); solid++;
          }
          if (solid < 4000 || solid > 56000 || left < 2 || right > 254 || top < 2 || bottom > 254) throw new Error(`Bad alpha/cell boundary at ${row},${col}: ${[left, top, right, bottom, solid]}`);
          const x = Math.max(0, left - 2), y = Math.max(0, top - 2);
          cells.push({ x: col * 256 + x, y: row * 256 + y, width: Math.min(256, right + 2) - x, height: Math.min(256, bottom + 2) - y, left: x, foot: bottom - y });
        }
        frames.push(cells);
      }
      return { frames, encoded: canvas.toDataURL('image/webp', .92).split(',')[1] };
    }, data);
    const file = `naiwa-${name}-v1.webp`;
    const bytes = Buffer.from(result.encoded, 'base64');
    await writeFile(`assets/animation/${file}`, bytes);
    const scales = { motion: [1, 1, 1.2, 1], combat: [1.05, 1.05, 1.05, 1.05], footwork: [1, 1, 1.25, 1.15] };
    atlases[name] = { file, frames: result.frames, scales: scales[name] };
    console.log(`${file}: 24 alpha frames, ${Math.round(bytes.length / 1024)} KiB`);
  }
  await writeFile('js/frog-atlas.js', `// Generated by scripts/prepare-frog-frames.mjs; coordinates preserve alpha and foot anchors.\nexport const FROG_ATLASES = ${JSON.stringify(atlases, null, 2)};\n`);
} finally { await browser.close(); }
